        if (min(conflicts)) &gt; conflicts_current_state:
          return None  # No improvement, local maxima

        if (min(conflicts)) == conflicts_current_state:
          side_moves += 1  # Plateau

        if side_moves &gt; MAX_SIDE_MOVES:
